def flaky_tests(runs):
    seen = {}
    for commit, test, outcome in runs:
        seen.setdefault((commit, test), set()).add(outcome)
    return sorted({test for (commit, test), outs in seen.items() if len(outs) > 1})

function quarantineList(results, threshold) {
  const out = [];
  for (const [test, runs] of Object.entries(results)) {
    const fails = runs.filter(r => r === 'fail').length;
    if (fails === 0 || fails === runs.length) continue;
    const rate = Math.round((fails / runs.length) * 100) / 100;
    if (rate >= threshold) out.push({ test, rate });
  }
  return out.sort((a, b) => b.rate - a.rate || a.test.localeCompare(b.test));
}
